const long long MOD = 1e9+7;
long long fact[N], invf[N];
long long power(long long a,long long n){ long long r=1;a%=MOD;
    while(n){ if(n&1) r=r*a%MOD; a=a*a%MOD; n>>=1; } return r; }
void init(){
    fact[0]=1;
    for(int i=1;i<N;++i) fact[i]=fact[i-1]*i%MOD;
    invf[N-1]=power(fact[N-1], MOD-2);
    for(int i=N-2;i>=0;--i) invf[i]=invf[i+1]*(i+1)%MOD;
}
long long C(int n,int k){
    if(k<0||k>n) return 0;
    return fact[n]*invf[k]%MOD*invf[n-k]%MOD;
}

MOD = 10**9 + 7
N = 200001
fact = [1] * N
inv_fact = [1] * N

def init():
    for i in range(1, N):
        fact[i] = fact[i-1] * i % MOD
    inv_fact[N-1] = pow(fact[N-1], MOD - 2, MOD)   # Fermat inverse
    for i in range(N - 2, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def C(n, k):
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD
